function validate([title]) {
  if (typeof title !== 'string' || title.length < 1 || title.length > 100) return 'title has 1 to 100 characters.';
  if (!/^[A-Za-z]+( [A-Za-z]+)*$/.test(title)) return 'title is letters-only words separated by single spaces.';
  return null;
}

