function capitalizeTitle(title) {
  const words = title.split(' ');
  const result = [];

  for (const word of words) {
    const lower = word.toLowerCase();
    if (lower.length <= 2) {
      result.push(lower);
    } else {
      result.push(lower[0].toUpperCase() + lower.slice(1));
    }
  }
  return result.join(' ');
}

brute:
function capitalizeTitle(title) {
  // Scan character by character; at each space (or the end) rewrite the word that just ended.
  let out = '';
  let start = 0;
  for (let i = 0; i <= title.length; i++) {
    if (i < title.length && title[i] !== ' ') continue;
    for (let j = start; j < i; j++) {
      const code = title.charCodeAt(j);
      const isUpper = code >= 65 && code <= 90;
      const wantUpper = j === start && i - start >= 3;
      if (wantUpper && !isUpper) out += String.fromCharCode(code - 32);
      else if (!wantUpper && isUpper) out += String.fromCharCode(code + 32);
      else out += title[j];
    }
    if (i < title.length) out += ' ';
    start = i + 1;
  }
  return out;
}

