function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const letter = () => String.fromCharCode((rand() < 0.5 ? 65 : 97) + pick(0, 25));
  const word = (maxLength) => Array.from({ length: pick(1, maxLength) }, letter).join('');
  if (size === 'small') {
    return [Array.from({ length: pick(1, 5) }, () => word(5)).join(' ')];
  }
  // Fill up to the 100-character limit with words of mixed lengths.
  let title = word(8);
  for (;;) {
    const next = word(pick(0, 2) === 0 ? 2 : 10);
    if (title.length + 1 + next.length > 100) break;
    title += ' ' + next;
  }
  return [title];
}
